const http = require('http');
const srv = http.createServer((req, res) => { let n = 0, s = ''; req.on('data', (c) => { n += c.length; s += c; }); req.on('end', () => res.end(`cl=${req.headers['content-length']} te=${req.headers['transfer-encoding']} got=${n} tail=${s.slice(-3)}`)); });
srv.listen(0, '127.0.0.1', () => { const q = http.request({ host: '127.0.0.1', port: srv.address().port, method: 'POST', path: '/', headers: { 'content-length': 9 } }, (res) => { let b = ''; res.on('data', (c) => (b += c)); res.on('end', () => { console.log('syncwithcl →', b); srv.close(); }); }); q.on('error', (e) => { console.log('syncwithcl error', e.code); srv.close(); }); q.write('aaa'); q.write('bbb'); q.end('ccc'); });
